// Fixtures for the answer-quality check of result compression (issue #205, design section 8.5). Every fixture is
// generated by a formula, so the answer to each question is known. Synthetic data only: no real names or addresses.

func issuesText() string {
	verbs := []string{"Fix", "Add", "Remove", "Update", "Document"}
	nouns := []string{"parser", "cache", "retry loop", "auth flow", "exporter", "scheduler", "linter"}
	var list []map[string]any
	for i := 1; i <= 60; i++ {
		labels := []any{map[string]any{"name": "area/api", "color": "0e8a16"}}
		if i%10 == 0 {
			labels = append(labels, map[string]any{"name": "bug", "color": "d73a4a"})
		}
		if i%5 == 0 {
			labels = append(labels, map[string]any{"name": "docs", "color": "0075ca"})
		}
		state := "open"
		if i%12 == 1 {
			state = "closed"
		}
		list = append(list, map[string]any{
			"number": i, "title": fmt.Sprintf("%s %s in module %d", verbs[i%5], nouns[i%7], i), "state": state,
			"user":     map[string]any{"login": fmt.Sprintf("dev%d", i%6), "id": 500 + i%6, "type": "User"},
			"labels":   labels,
			"body":     "Steps:\n1. run the suite\n2. see the failure \"timeout\"\n3. attach the log",
			"comments": i % 4,
		})
	}
	b, _ := json.MarshalIndent(list, "", "  ")
	return string(b)
}

func rowAmount(id int) string { return fmt.Sprintf("%d.%02d", 100+id*37%900, id*11%100) }

func rowsText() string {
	var rows []map[string]any
	for id := 0; id < 150; id++ {
		status := "ok"
		switch id % 25 {
		case 7:
			status = "failed"
		case 9:
			status = "retry"
		}
		var note any
		if id%2 == 1 {
			note = fmt.Sprintf("batch-%d", id/10)
		}
		rows = append(rows, map[string]any{
			"id": id, "name": fmt.Sprintf("item-%d", id), "status": status, "amount": json.Number(rowAmount(id)),
			"region": []string{"eu", "us", "ap"}[id%3], "note": note,
		})
	}
	b, _ := json.MarshalIndent(rows, "", "  ")
	return string(b)
}

var logFiles = []string{"main", "db", "cache"}

func logStamp(i int) string { return fmt.Sprintf("2026-03-01T10:%02d:%02dZ", i/60, i%60) }

func logText() string {
	var b strings.Builder
	for i := 0; i < 800; i++ {
		ts := logStamp(i)
		if i >= 100 && (i-100)%90 == 0 && (i-100)/90 < 8 {
			k := (i - 100) / 90
			fmt.Fprintf(&b, "%s ERROR request failed: upstream timeout id=%d\n", ts, 9000+k*17)
			fmt.Fprintf(&b, "goroutine 41 [running]:\nmain.handle%d(0xc000123456)\n\t/app/%s.go:%d +0x1d\n", k%3, logFiles[k%3], 80+k*7)
			continue
		}
		switch {
		case i == 400:
			fmt.Fprintf(&b, "%s WARN disk usage at 91%% on /var/lib\n", ts)
		case i == 550:
			fmt.Fprintf(&b, "%s WARN slow query took=1840ms table=orders\n", ts)
		case i%10 == 3:
			fmt.Fprintf(&b, "%s INFO served request path=/api/items/%d status=200\n", ts, i%97)
		default:
			fmt.Fprintf(&b, "%s INFO health check ok\n", ts)
		}
	}
	return b.String()
}

func testsText() string {
	failAt := map[int][2]string{
		60:  {"TestParseHeader", "parse_test.go:31: got \"Content-Type\", want \"content-type\""},
		120: {"TestRetryBackoff", "retry_test.go:58: got 3s, want 4s"},
		180: {"TestCacheEvict", "cache_test.go:77: got 17 entries, want 16"},
	}
	var b strings.Builder
	for i := 0; i < 223; i++ {
		if f, ok := failAt[i]; ok {
			fmt.Fprintf(&b, "=== RUN   %s\n    %s\n--- FAIL: %s (0.00s)\n", f[0], f[1], f[0])
			continue
		}
		fmt.Fprintf(&b, "=== RUN   TestCase%d\n--- PASS: TestCase%d (0.01s)\n", i, i)
	}
	b.WriteString("FAIL\nFAIL\texample.com/app/pkg\t0.412s\n")
	return b.String()
}

const passingTests = 220 // 223 tests, 3 of them fail

func csvAmount(id int) string { return fmt.Sprintf("%d.%02d", id*13%500, id%100) }

func csvText() string {
	var b strings.Builder
	b.WriteString("id,customer,category,amount,note\n")
	for id := 0; id < 200; id++ {
		cat := []string{"order", "ship", "invoice"}[id%3]
		if id%9 == 2 {
			cat = "refund"
		}
		note := `"called back, left voicemail"`
		if id%10 == 4 {
			note = "\"said ok\nrefund pending\""
		}
		fmt.Fprintf(&b, "%d,customer-%d,%s,%s,%s\n", id, id, cat, csvAmount(id), note)
	}
	return b.String()
}

func tableText() string {
	degraded := map[int]bool{37: true, 121: true, 166: true}
	var b strings.Builder
	b.WriteString("| ID        | Name           | Region | Status     |\n|-----------|----------------|--------|------------|\n")
	for i := 0; i < 200; i++ {
		st := "healthy"
		if degraded[i] {
			st = "degraded"
		}
		fmt.Fprintf(&b, "| %-9d | %-14s | %-6s | %-10s |\n", i, fmt.Sprintf("service-%d", i), []string{"eu", "us"}[i%2], st)
	}
	return b.String()
}

func podsText() string {
	var b strings.Builder
	b.WriteString("apiVersion: v1\nitems:\n")
	for i := 0; i < 40; i++ {
		ns, restarts := "default", 0
		if i%4 == 0 {
			ns = "staging"
		}
		if i == 23 {
			restarts = 7
		}
		fmt.Fprintf(&b, "- apiVersion: v1\n  kind: Pod\n  metadata:\n    name: web-%d\n    managedFields:\n    - apiVersion: v1\n      fieldsType: FieldsV1\n      fieldsV1:\n        f:metadata:\n          f:labels:\n            .: {}\n      manager: kubectl\n    namespace: %s\n  spec:\n    containers:\n    - image: nginx\n      name: web\n  status:\n    containerStatuses:\n    - name: web\n      restartCount: %d\n", i, ns, restarts)
	}
	b.WriteString("kind: List\n")
	return b.String()
}

// bothText and bothStructured differ on purpose: a test that must tell which of the two a client sends to the
// model looks for TXTMARK or STRUCTMARK in the model request.
func bothText() string {
	var b strings.Builder
	for i := 0; i < 40; i++ {
		fmt.Fprintf(&b, "TXTMARK alpha text line %d with some filler words for size\n", i)
	}
	return b.String()
}

func bothStructured() map[string]any {
	rows := make([]string, 60)
	for i := range rows {
		rows[i] = fmt.Sprintf("STRUCTMARK beta structured row %d with some other filler words", i)
	}
	return map[string]any{"rows": rows}
}
